use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut lc: Vec<int> = []
    let mut rc: Vec<int> = []
    let mut root: int = -1
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let mut arg: int = 0
        if parts.len() > 1 {
            arg = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            if root == -1 {
                keys.push(arg)
                lc.push(-1)
                rc.push(-1)
                root = 0
                println("ok")
            } else {
                let mut cur: int = root
                let mut done = false
                while !done {
                    if keys[cur] == arg {
                        println("dup")
                        done = true
                    } else if arg < keys[cur] {
                        if lc[cur] == -1 {
                            let id: int = keys.len() as int
                            keys.push(arg)
                            lc.push(-1)
                            rc.push(-1)
                            lc[cur] = id
                            println("ok")
                            done = true
                        } else {
                            cur = lc[cur]
                        }
                    } else {
                        if rc[cur] == -1 {
                            let id: int = keys.len() as int
                            keys.push(arg)
                            lc.push(-1)
                            rc.push(-1)
                            rc[cur] = id
                            println("ok")
                            done = true
                        } else {
                            cur = rc[cur]
                        }
                    }
                }
            }
        } else if cmd == "contains" {
            let mut cur: int = root
            let mut found = false
            while cur != -1 && !found {
                if keys[cur] == arg {
                    found = true
                } else if arg < keys[cur] {
                    cur = lc[cur]
                } else {
                    cur = rc[cur]
                }
            }
            if found {
                println("yes")
            } else {
                println("no")
            }
        } else if cmd == "delete" {
            let mut cur: int = root
            let mut parent: int = -1
            let mut found = false
            while cur != -1 && !found {
                if keys[cur] == arg {
                    found = true
                } else {
                    parent = cur
                    if arg < keys[cur] {
                        cur = lc[cur]
                    } else {
                        cur = rc[cur]
                    }
                }
            }
            if !found {
                println("missing")
            } else {
                if lc[cur] != -1 && rc[cur] != -1 {
                    let mut sp: int = cur
                    let mut s: int = rc[cur]
                    while lc[s] != -1 {
                        sp = s
                        s = lc[s]
                    }
                    keys[cur] = keys[s]
                    if sp == cur {
                        rc[sp] = rc[s]
                    } else {
                        lc[sp] = rc[s]
                    }
                } else {
                    let mut child: int = lc[cur]
                    if child == -1 {
                        child = rc[cur]
                    }
                    if parent == -1 {
                        root = child
                    } else if lc[parent] == cur {
                        lc[parent] = child
                    } else {
                        rc[parent] = child
                    }
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            if root == -1 {
                println("<empty>")
            } else {
                let mut out: Vec<string> = []
                let mut stack: Vec<int> = []
                let mut cur: int = root
                while cur != -1 || stack.len() > 0 {
                    while cur != -1 {
                        stack.push(cur)
                        cur = lc[cur]
                    }
                    let n: int = stack.pop().unwrap_or(-1)
                    out.push("${keys[n]}")
                    cur = rc[n]
                }
                println(out.join(" "))
            }
        } else if cmd == "height" {
            let mut h: int = 0
            if root != -1 {
                let mut level: Vec<int> = [root]
                while level.len() > 0 {
                    h += 1
                    let mut next: Vec<int> = []
                    for n in level {
                        if lc[n] != -1 {
                            next.push(lc[n])
                        }
                        if rc[n] != -1 {
                            next.push(rc[n])
                        }
                    }
                    level = next
                }
            }
            println("${h}")
        } else if cmd == "min" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur: int = root
                while lc[cur] != -1 {
                    cur = lc[cur]
                }
                println("${keys[cur]}")
            }
        } else if cmd == "max" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur: int = root
                while rc[cur] != -1 {
                    cur = rc[cur]
                }
                println("${keys[cur]}")
            }
        }
    }
